// ===== BankGPT Chat – Code node "Reply" (Run Once for All Items) =====
// Formats AnswerFlow's result for the chat window and remembers this turn for follow-ups.
const C = $('Context').first().json;
let question = C.question;
try { question = $('Rewrite').first().json.question || question; } catch (e) { /* no rewrite this turn */ }
const r = $input.first().json;
const answer = String(r.answer || "I don't know. Please call one of our branches.").trim();
let text = answer;
const src = (r.sources || []).slice(0, 3);
if (src.length) text += '\n\nSources:\n' + src.map(u => '- ' + u).join('\n');

const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
const hist = store.sessions[C.sessionId] || [];
hist.push({ q: question, a: answer.slice(0, 600) });
store.sessions[C.sessionId] = hist.slice(-6);
const ids = Object.keys(store.sessions);                 // keep at most 300 conversations
for (const id of ids.slice(0, Math.max(0, ids.length - 300))) delete store.sessions[id];

return [{ json: { output: text } }];

// ===== BankGPT Chat – Code node "Context" (Run Once for All Items) =====
// Reads the chat message and this conversation's last few turns (kept in workflow static data,
// which n8n saves for runs from the published chat page, not for manual test runs).
const t = $input.first().json;
const sessionId = String(t.sessionId || 'default');
const message = String(t.chatInput || '').trim();
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
const hist = (store.sessions[sessionId] || []).slice(-3);
const history = hist.map(h => `Member: ${h.q}\nAssistant: ${h.a}`).join('\n\n');
return [{ json: { sessionId, message, question: message, hasHistory: hist.length > 0, history } }];

// ===== BankGPT Chat – Code node "Use rewrite" (Run Once for All Items) =====
// Takes the rewritten question from the "Rewrite" model node; falls back to the original message.
const C = $('Context').first().json;
const SKIP = new Set(['type', 'format', 'id', 'model', 'role', 'status', 'object', 'finish_reason', 'refusal']);
function findText(o) {
  if (typeof o === 'string') return o.includes(' ') ? o : null;
  if (Array.isArray(o)) { for (const x of o) { const t = findText(x); if (t) return t; } return null; }
  if (o && typeof o === 'object') {
    for (const k of ['content', 'text', 'output', 'message', 'response', 'choices']) {
      if (k in o) { const t = findText(o[k]); if (t) return t; }
    }
    for (const [k, v] of Object.entries(o)) { if (SKIP.has(k)) continue; const t = findText(v); if (t) return t; }
  }
  return null;
}
let q = (findText($input.first().json) || '').trim().replace(/^["'“]|["'”]$/g, '').replace(/^Output:\s*/i, '');
if (!q || q.length > 400) q = C.message;
return [{ json: { ...C, question: q } }];
